  },
}

export function creatureStyle(id) {
  return SPECIES_STYLE[id] || SPECIES_STYLE.brasalume
}

function quadruped(style) {
  const root = new THREE.Group()
  const fur = mat(style.body, { roughness: 0.88 })
  const bellyMat = mat(style.belly, { roughness: 0.9 })
  const accentMat = mat(style.accent, { roughness: 0.7, emissive: style.accent, emissiveIntensity: 0.12 })
  const darkMat = mat(style.dark, { roughness: 0.92 })
  const eyeMat = new THREE.MeshBasicMaterial({ color: style.eye })
  const blackMat = new THREE.MeshBasicMaterial({ color: 0x171a16 })
  const glowMatC = new THREE.MeshBasicMaterial({ color: style.glow })

  const body = mesh(ico(1, 1), fur, 0, 0.72, 0)
  body.scale.set(0.4, 0.38, 0.62)
  root.add(body)
  const belly = mesh(ico(1, 1), bellyMat, 0, 0.62, 0.06)
  belly.scale.set(0.31, 0.24, 0.47)
  root.add(belly)

  const head = new THREE.Group()
  head.position.set(0, 0.92, 0.5)
  root.add(head)
  const skull = mesh(ico(1, 1), fur, 0, 0, 0)
  skull.scale.set(0.29, 0.27, 0.3)
  head.add(skull)
  const muzzle = mesh(ico(1, 0), bellyMat, 0, -0.06, 0.24)
  muzzle.scale.set(0.14, 0.11, 0.14)
  head.add(muzzle)
  const nose = mesh(ico(0.045, 0), darkMat, 0, -0.04, 0.37)
  head.add(nose)
  const eyeL = mesh(ico(0.048, 0), eyeMat, -0.13, 0.06, 0.22)
  const eyeR = eyeL.clone()
  eyeR.position.x = 0.13
  head.add(eyeL, eyeR)
  const pupilL = mesh(ico(0.022, 0), blackMat, -0.135, 0.06, 0.26)
  const pupilR = pupilL.clone()
  pupilR.position.x = 0.135
  head.add(pupilL, pupilR)

  const earL = mesh(cone(0.1, 0.32, 4), fur, -0.17, 0.24, -0.02)
  earL.rotation.z = 0.3
  const earR = earL.clone()
  earR.position.x = 0.17
  earR.rotation.z = -0.3
  head.add(earL, earR)
  const earInnerL = mesh(cone(0.05, 0.18, 4), accentMat, -0.17, 0.24, 0.01)
  earInnerL.rotation.z = 0.3
  const earInnerR = earInnerL.clone()
  earInnerR.position.x = 0.17
  earInnerR.rotation.z = -0.3
  head.add(earInnerL, earInnerR)

  const legs = []
  for (let i = 0; i < 4; i++) {
    const front = i < 2
    const side = i % 2 === 0 ? -1 : 1
    const leg = new THREE.Group()
    leg.position.set(side * 0.21, 0.52, front ? 0.38 : -0.36)
    const upper = mesh(box(0.12, 0.4, 0.15), fur, 0, -0.2, 0)
    const paw = mesh(box(0.14, 0.12, 0.19), darkMat, 0, -0.44, 0.025)
    leg.add(upper, paw)
    root.add(leg)
    legs.push(leg)
  }

  const tail = new THREE.Group()
  tail.position.set(0, 0.84, -0.56)
  root.add(tail)
  let tailSeg = mesh(ico(0.15, 0), fur, 0, 0, 0)
  tail.add(tailSeg)
  const tail2 = mesh(ico(0.12, 0), accentMat, 0, 0.04, -0.18)
  tail.add(tail2)
  tail.rotation.x = -0.5

  const parts = { body, head, legs, tail, ears: [earL, earR] }

  // per-species details are added by caller
  return { root, parts, mats: { fur, bellyMat, accentMat, darkMat, eyeMat, glowMatC } }
}

function golem(style) {
  const root = new THREE.Group()
  const stone = mat(style.body, { roughness: 0.95 })
  const stoneLight = mat(style.belly, { roughness: 0.95 })
  const dark = mat(style.dark, { roughness: 1 })
  const crack = new THREE.MeshStandardMaterial({ color: style.accent, emissive: style.accent, emissiveIntensity: 1.7, flatShading: true })
  const eyeMat = new THREE.MeshBasicMaterial({ color: style.eye })

  const hips = mesh(ico(0.55, 0), stone, 0, 0.95, 0)
  hips.scale.set(1, 0.65, 0.8)
  root.add(hips)
  const body = new THREE.Group()
  body.position.y = 1.35
  root.add(body)
  const chest = mesh(ico(0.65, 0), stone, 0, 0.1, 0)
  chest.scale.set(0.95, 0.85, 0.72)
  body.add(chest)
  const chestLight = mesh(ico(0.4, 0), stoneLight, 0, 0.2, 0.35)
  chestLight.scale.set(0.9, 0.6, 0.4)
  body.add(chestLight)
  const crack1 = mesh(box(0.06, 0.55, 0.05), crack, 0.18, 0.15, 0.48)
  crack1.rotation.z = 0.35
  const crack2 = mesh(box(0.04, 0.35, 0.05), crack, -0.16, 0.08, 0.5)
  crack2.rotation.z = -0.5
  body.add(crack1, crack2)
  const heart = mesh(ico(0.15, 0), crack, 0, 0.15, 0.45)
  body.add(heart)

  const head = new THREE.Group()
  head.position.set(0, 0.85, 0.12)
  body.add(head)
  const skull = mesh(box(0.5, 0.46, 0.46), stone, 0, 0, 0)
  head.add(skull)
  const jaw = mesh(box(0.42, 0.16, 0.4), stoneLight, 0, -0.29, 0.06)
  head.add(jaw)
  const brow = mesh(box(0.56, 0.1, 0.14), dark, 0, 0.13, 0.22)
  head.add(brow)
  const eyeL = mesh(box(0.11, 0.06, 0.04), eyeMat, -0.15, 0.04, 0.24)
  const eyeR = eyeL.clone()
  eyeR.position.x = 0.15
  head.add(eyeL, eyeR)

  const arms = []
  for (let i = 0; i < 2; i++) {
    const side = i === 0 ? -1 : 1
    const arm = new THREE.Group()
    arm.position.set(side * 0.68, 1.6, 0)
    const upper = mesh(ico(0.28, 0), stone, side * 0.05, -0.1, 0)
    upper.scale.set(0.9, 1.3, 0.9)
    const fist = mesh(ico(0.32, 0), stoneLight, side * 0.08, -0.55, 0)
    const spike = mesh(cone(0.1, 0.3, 4), crack, side * 0.08, -0.82, 0)
    spike.rotation.z = Math.PI
    arm.add(upper, fist, spike)
    arm.rotation.z = side * 0.18
    root.add(arm)
    arms.push(arm)
  }

  const legs = []
  for (let i = 0; i < 2; i++) {
    const side = i === 0 ? -1 : 1
    const leg = new THREE.Group()
    leg.position.set(side * 0.26, 0.75, 0)
    const thigh = mesh(ico(0.27, 0), stone, 0, -0.1, 0)
    thigh.scale.set(0.9, 1.0, 0.9)
    const foot = mesh(box(0.35, 0.18, 0.44), stoneLight, 0, -0.37, 0.06)
    leg.add(thigh, foot)
    root.add(leg)
    legs.push(leg)
  }

  const runes = []
  for (let i = 0; i < 5; i++) {
    const r = mesh(box(0.03, 0.14, 0.03), crack, (i - 2) * 0.13, 1.9 - Math.abs(i - 2) * 0.12, 0.4)
    body.add(r)
    runes.push(r)
  }

  return {
    root,
    parts: { body, head, arms, legs, heart, crack1, crack2, runes },
    mats: { fur: stone, bellyMat: stoneLight, accentMat: crack, darkMat: dark, eyeMat },
  }
}

function bird(style) {
  const root = new THREE.Group()
  const feather = mat(style.body, { roughness: 0.8 })
  const light = mat(style.belly, { roughness: 0.85 })
  const accent = mat(style.accent, { roughness: 0.6, emissive: style.accent, emissiveIntensity: 0.2 })
  const dark = mat(style.dark, { roughness: 0.85 })
  const eyeMat = new THREE.MeshBasicMaterial({ color: style.eye })

  const body = new THREE.Group()
  body.position.y = 1.05
  root.add(body)
  const torso = mesh(ico(0.38, 1), feather, 0, 0, 0)
  torso.scale.set(0.9, 1.1, 0.85)
  body.add(torso)
  const chest = mesh(ico(0.26, 1), light, 0, -0.06, 0.18)
  chest.scale.set(0.9, 1, 0.6)
  body.add(chest)
  const tail = mesh(cone(0.3, 0.8, 5), accent, 0, -0.2, -0.55)
  tail.rotation.x = -1.9
  body.add(tail)

  const head = new THREE.Group()
  head.position.set(0, 0.4, 0.16)
  body.add(head)
  const skull = mesh(ico(0.24, 1), feather, 0, 0, 0)
  head.add(skull)
  const beak = mesh(cone(0.09, 0.26, 4), accent, 0, -0.02, 0.24)
  beak.rotation.x = Math.PI / 2
  head.add(beak)
  const eyeL = mesh(ico(0.04, 0), eyeMat, -0.12, 0.06, 0.17)
  const eyeR = eyeL.clone()
  eyeR.position.x = 0.12
  head.add(eyeL, eyeR)
  const crest = mesh(cone(0.08, 0.4, 4), accent, 0, 0.24, -0.04)
  crest.rotation.x = -0.35
  head.add(crest)
  const crest2 = mesh(cone(0.06, 0.3, 4), feather, 0.1, 0.22, -0.08)
  crest2.rotation.z = -0.5
  head.add(crest2)

  const wings = []
  for (let i = 0; i < 2; i++) {
    const side = i === 0 ? -1 : 1
    const wing = new THREE.Group()
    wing.position.set(side * 0.28, 1.15, 0)
    const shape = new THREE.Shape()
    shape.moveTo(0, 0)
    shape.lineTo(side * 1.15, 0.25)
    shape.lineTo(side * 1.35, 0.05)
    shape.lineTo(side * 0.95, -0.3)
    shape.lineTo(side * 0.3, -0.28)
    shape.lineTo(0, -0.1)
    const geo = new THREE.ShapeGeometry(shape)
    geo.rotateX(-Math.PI / 2)
    const featherMat = mat(style.body, { roughness: 0.85, side: THREE.DoubleSide })
    const w = new THREE.Mesh(geo, featherMat)
    const tip = mesh(cone(0.14, 0.5, 4), accent, side * 1.15, 0.2, 0.02)
    tip.rotation.z = side * 1.5
    wing.add(w, tip)
    root.add(wing)
    wings.push(wing)
  }

  const legs = []
  for (let i = 0; i < 2; i++) {
    const side = i === 0 ? -1 : 1
    const leg = new THREE.Group()
    leg.position.set(side * 0.12, 0.82, 0)
    const shin = mesh(cyl(0.025, 0.03, 0.3, 4), dark, 0, -0.15, 0)
    const foot = mesh(cone(0.08, 0.16, 3), accent, 0, -0.31, 0.04)
    foot.rotation.x = Math.PI / 2
    leg.add(shin, foot)
    root.add(leg)
    legs.push(leg)
  }

  return {
    root,
    parts: { body, head, wings, legs, tail },
    mats: { fur: feather, bellyMat: light, accentMat: accent, darkMat: dark, eyeMat },
  }
}

function wraith(style) {
  const root = new THREE.Group()
  const cloak = mat(style.body, { roughness: 0.92, side: THREE.DoubleSide })
  const inner = mat(style.belly, { roughness: 0.9 })
  const accent = new THREE.MeshStandardMaterial({ color: style.accent, emissive: style.accent, emissiveIntensity: 1.2, flatShading: true })
  const eyeMat = new THREE.MeshBasicMaterial({ color: style.eye })

  const body = new THREE.Group()
  body.position.y = 1.05
  root.add(body)
  const cloakMesh = mesh(new THREE.ConeGeometry(0.58, 1.5, 8, 1, true), cloak, 0, 0.08, 0)
  body.add(cloakMesh)
  const chest = mesh(ico(0.3, 1), inner, 0, 0.25, 0.08)
  chest.scale.set(0.8, 1.0, 0.6)
  body.add(chest)
  const hood = mesh(new THREE.ConeGeometry(0.36, 0.6, 7, 1, true), cloak, 0, 0.65, -0.02)
  body.add(hood)
  const face = mesh(ico(0.19, 1), mat(0x1b1730, { roughness: 1 }), 0, 0.58, 0.13)
  face.scale.set(0.9, 1, 0.55)
  body.add(face)
  const eyeL = mesh(box(0.075, 0.025, 0.02), eyeMat, -0.075, 0.6, 0.27)
  const eyeR = eyeL.clone()
  eyeR.position.x = 0.075
  body.add(eyeL, eyeR)
  const mouth = mesh(box(0.1, 0.018, 0.02), accent, 0, 0.53, 0.26)
  body.add(mouth)

  const shoulderL = mesh(ico(0.16, 0), cloak, -0.36, 0.45, 0)
  const shoulderR = shoulderL.clone()
  shoulderR.position.x = 0.36
  body.add(shoulderL, shoulderR)
  const armL = new THREE.Group()
  armL.position.set(-0.4, 0.42, 0)
  const armLMesh = mesh(cone(0.08, 0.55, 5), cloak, -0.06, -0.22, 0)
  armLMesh.rotation.z = Math.PI
  armL.add(armLMesh)
  const armR = armL.clone()
  armR.position.x = 0.4
  armR.scale.x = -1
  body.add(armL, armR)

  const wisps = []
  for (let i = 0; i < 5; i++) {
    const w = new THREE.Group()
    const a = (i / 5) * Math.PI * 2
    w.position.set(Math.cos(a) * 0.28, -0.45 - (i % 2) * 0.2, Math.sin(a) * 0.28)
    const strand = mesh(new THREE.ConeGeometry(0.1, 0.7, 4, 1, true), cloak, 0, -0.28, 0)
    strand.rotation.x = Math.PI
    w.add(strand)
    body.add(w)
    wisps.push(w)
  }

  const orbs = []
  for (let i = 0; i < 2; i++) {
    const orb = mesh(ico(0.08, 0), accent, i ? 0.6 : -0.6, 0.4 + i * 0.2, 0.1)
    const glow = glowSprite(style.glow, 0.8, 0.8)
    glow.position.copy(orb.position)
    body.add(orb, glow)
    orbs.push({ orb, glow, phase: i * 2.1 })
  }

  return {
    root,
    parts: { body, head: body, arms: [armL, armR], wisps, orbs, eyeL, eyeR, mouth },
    mats: { fur: cloak, bellyMat: inner, accentMat: accent, eyeMat },
  }
}

const BOSS_CROWN = new THREE.MeshStandardMaterial({ color: 0xe9c46a, metalness: 0.75, roughness: 0.3, emissive: 0x6b4a12, emissiveIntensity: 0.35 })

export function buildCreatureModel(speciesId, { boss = false, companion = false } = {}) {
  const style = creatureStyle(speciesId)
  let built
  if (style.root === 'golem') built = golem(style)
  else if (style.root === 'bird') built = bird(style)
  else if (style.root === 'wraith') built = wraith(style)
  else built = quadruped(style)

  const { root, parts, mats } = built

  // species decorations
  if (speciesId === 'brasalume') {
    const flameMat = new THREE.MeshBasicMaterial({ color: 0xffb35c, transparent: true, opacity: 0.9 })
    const flame = new THREE.Group()
    flame.position.set(0, 0.02, -0.2)
    for (let i = 0; i < 3; i++) {
      const f = mesh(cone(0.16 - i * 0.03, 0.55 + i * 0.22, 5), flameMat, 0, 0.32 + i * 0.18, -0.02 - i * 0.05)
      f.rotation.x = -0.2
      flame.add(f)
    }
    const halo = glowSprite(0xff8a3c, 1.7, 0.65)
    halo.position.y = 0.42
    flame.add(halo)
    parts.tail.add(flame)
    parts.flame = flame
    parts.flameMat = flameMat

    const crestMat = mat(style.accent, { emissive: style.accent, emissiveIntensity: 0.5 })
    for (let i = 0; i < 3; i++) {
      const spike = mesh(cone(0.06, 0.28 - i * 0.05, 4), crestMat, 0, 0.28 + (i - 1) * 0.04, -0.02 - i * 0.09)
      spike.rotation.x = -0.4 - i * 0.12
      parts.head.add(spike)
    }
    const backFlame = mesh(cone(0.16, 0.5, 5), flameMat, 0, 0.88, -0.5)
    backFlame.rotation.x = -0.6
    root.add(backFlame)
  }

  if (speciesId === 'aquari') {
    const finMat = mat(style.accent, { roughness: 0.5, emissive: style.accent, emissiveIntensity: 0.22, side: THREE.DoubleSide })
    const backFin = mesh(cone(0.12, 0.55, 4), finMat, 0, 1.05, -0.1)
    backFin.rotation.x = -0.3
    root.add(backFin)
    const tailFin = mesh(cone(0.3, 0.5, 4), finMat, 0, 0.85, -0.78)
    tailFin.rotation.x = Math.PI / 2
    tailFin.scale.set(1, 1, 0.3)
    root.add(tailFin)
    for (let i = 0; i < 3; i++) {
      const ripple = mesh(ico(0.035, 0), new THREE.MeshBasicMaterial({ color: 0xc9fff8, transparent: true, opacity: 0.8 }), (i - 1) * 0.14, 1.12 + i * 0.04, 0.02)
      ripple.userData.float = i * 1.7
      root.add(ripple)
      parts[`ripple${i}`] = ripple
    }
    const droplet = glowSprite(0x7ff4ef, 1.3, 0.5)
    droplet.position.set(0, 1.2, 0.28)
    root.add(droplet)
    parts.droplet = droplet
  }

  if (speciesId === 'musgo') {
    const mossMat = mat(0x7da84f, { roughness: 1 })
    for (let i = 0; i < 5; i++) {
      const clump = mesh(ico(0.16 + Math.random() * 0.12, 0), mossMat, (Math.random() - 0.5) * 0.4, 0.98 + Math.random() * 0.1, -0.25 + Math.random() * 0.45)
      clump.scale.y = 0.6
      root.add(clump)
    }
    const tuskMat = mat(0xf0e6c8, { roughness: 0.5 })
    const tuskL = mesh(cone(0.045, 0.3, 4), tuskMat, -0.17, -0.06, 0.34)
    tuskL.rotation.x = 0.9
    const tuskR = tuskL.clone()
    tuskR.position.x = 0.17
    parts.head.add(tuskL, tuskR)
    const maneMat = mat(style.dark, { roughness: 1 })
    for (let i = 0; i < 4; i++) {
      const spike = mesh(cone(0.09, 0.36, 4), maneMat, (i - 1.5) * 0.1, 0.12 + i * 0.03, -0.1)
      spike.rotation.x = -0.9
      parts.head.add(spike)
    }
    const leafMat = new THREE.MeshBasicMaterial({ color: 0xa4e07a, transparent: true, opacity: 0.8 })
    for (let i = 0; i < 4; i++) {
      const leaf = mesh(cone(0.05, 0.2, 3), leafMat, (Math.random() - 0.5) * 0.5, 1.1 + Math.random() * 0.2, -0.2 + Math.random() * 0.4)
      leaf.rotation.z = Math.random() * 2
      root.add(leaf)
      parts[`leaf${i}`] = leaf
    }
  }

  if (speciesId === 'pedral') {
    const rockMat = mat(style.dark, { roughness: 1 })
    for (let i = 0; i < 6; i++) {
      const spike = mesh(cone(0.12, 0.4, 4), rockMat, (Math.random() - 0.5) * 0.8, 1.7 + Math.random() * 0.4, -0.35 + Math.random() * 0.3)
      spike.rotation.z = Math.random() * 0.8 - 0.4
      spike.rotation.x = -0.4
      root.add(spike)
    }
    parts.heartGlow = glowSprite(0xff9c58, 1.6, 0.6)
    parts.heartGlow.position.set(0, 1.5, 0.62)
    root.add(parts.heartGlow)
  }

  if (speciesId === 'zephyro') {
    for (let i = 0; i < 3; i++) {
      const feather = mesh(cone(0.07, 0.5, 4), mat(style.accent, { emissive: style.accent, emissiveIntensity: 0.3 }), 0, 0.1, -0.5 - i * 0.16)
      feather.rotation.x = -1.2 - i * 0.12
      feather.rotation.z = (i - 1) * 0.25
      parts.body.add(feather)
    }
    parts.gustGlow = glowSprite(0xb9a8ff, 1.8, 0.35)
    parts.gustGlow.position.set(0, 1.1, 0)
    root.add(parts.gustGlow)
  }

  if (speciesId === 'umbra') {
    const aura = glowSprite(style.glow, 2.4, 0.28)
    aura.position.y = 1.05
    root.add(aura)
    parts.aura = aura
  }

  if (boss) {
    const crown = new THREE.Group()
    crown.position.y = speciesId === 'umbra' ? 0.88 : speciesId === 'pedral' ? 0.9 : speciesId === 'zephyro' ? 0.68 : 0.36
    const ring = mesh(new THREE.TorusGeometry(0.28, 0.045, 4, 10), BOSS_CROWN, 0, 0, 0)
    ring.rotation.x = Math.PI / 2
    crown.add(ring)
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2
      const spike = mesh(cone(0.05, 0.22, 4), BOSS_CROWN, Math.cos(a) * 0.28, 0.08, Math.sin(a) * 0.28)
      crown.add(spike)
    }
    const halo = glowSprite(0xffd27a, 3.4, 0.3)
    halo.position.y = 0.1
    crown.add(halo)
    parts.head.add(crown)
    parts.crown = crown
    const auraSprite = glowSprite(style.aura, 6.5, 0.22)
    auraSprite.position.y = 1.2
    root.add(auraSprite)
    parts.bossAura = auraSprite
  }

  const scale = style.scale * (boss ? 2.05 : companion ? 0.78 : 1)
  root.scale.setScalar(scale)
  root.userData.species = speciesId
  root.userData.height = (style.root === 'golem' ? 2.1 : style.root === 'bird' ? 1.7 : style.root === 'wraith' ? 1.9 : 1.1) * scale
  shade(root)
  return { root, parts, mats, style }
}

export function createAura(color, scale = 3) {
  return glowSprite(color, scale, 0.3)
}

export { shade, glowSprite }

import * as THREE from 'three'
import { clamp, damp, dampAngle, lerp, easing, terrainSlope } from './engine.js'
import { buildPlayer } from './characters.js'
import { terrainHeight } from './world.js'

const ATTACKS = [
  { duration: 0.46, hitStart: 0.12, hitEnd: 0.22, damage: 12, stamina: 7, range: 3.4, arc: 1.15, knock: 2.0, lunge: 2.2 },
  { duration: 0.48, hitStart: 0.13, hitEnd: 0.23, damage: 14, stamina: 7, range: 3.5, arc: 1.2, knock: 2.2, lunge: 2.0 },
  { duration: 0.62, hitStart: 0.19, hitEnd: 0.29, damage: 26, stamina: 12, range: 3.9, arc: 1.5, knock: 4.2, lunge: 3.2 },
]
const HEAVY = { duration: 0.82, hitStart: 0.3, hitEnd: 0.42, damage: 42, stamina: 23, range: 4.3, arc: 1.7, knock: 6.5, lunge: 3.4 }
const DODGE_TIME = 0.42

export class Player {
  constructor(scene, world, audio) {
    this.world = world
    this.audio = audio
    this.model = buildPlayer()
    this.model.rotation.order = 'YXZ'
    scene.add(this.model)

    this.position = new THREE.Vector3(0, 0, 34)
    this.position.y = terrainHeight(0, 34)
    this.spawnPoint = this.position.clone()
    this.velocity = new THREE.Vector3()
    this.yaw = Math.PI
    this.modelYaw = Math.PI
    this.aimYaw = Math.PI

    this.level = 1
    this.xp = 0
    this.xpToNext = 90
    this.maxHp = 120
    this.hp = 120
    this.maxStamina = 100
    this.stamina = 100
    this.staminaDelay = 0
    this.walkPhase = 0
    this.idleTime = 0
    this.sprinting = false
    this.moving = false
    this.dead = false

    this.attack = null
    this.attackCooldown = 0
    this.comboStep = 0
    this.comboTimer = 0
    this.comboWindow = 0
    this.attackBuffer = 0
    this.heavyBuffer = 0
    this.dodgeBuffer = 0
    this.dodgeTimer = 0
    this.dodgeCooldown = 0
    this.invuln = 0
    this.hitstun = 0
    this.lastHurt = 99
    this.time = 0

    this.events = {
      onSlash: null, onHeavy: null, onDodge: null, onHurt: null,
      onDeath: null, onLevelUp: null, onStep: null, onStaminaFail: null,
      onCombo: null,
    }
    this.style = { trailColor: 0x9ffff0 }
    this.model.position.copy(this.position)
    this.model.rotation.y = this.yaw
  }

  get isAttacking() { return !!this.attack }
  get isDodging() { return this.dodgeTimer > 0 }
  get isBusy() { return this.isAttacking || this.isDodging || this.hitstun > 0 }
  get forward() { return new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw)) }

  setAim(yaw) { this.aimYaw = yaw }

  tryAttack(heavy = false) {
    if (this.dead || this.isDodging || this.hitstun > 0) return
    if (heavy) this.heavyBuffer = 0.24
    else this.attackBuffer = 0.26
  }

  tryDodge() {
    if (this.dead || this.hitstun > 0) return
    this.dodgeBuffer = 0.22
  }

  startDodge(moveDir) {
    if (this.stamina < 20) {
      this.events.onStaminaFail?.('Vigor insuficiente para esquivar')
      return
    }
    this.stamina -= 20
    this.staminaDelay = 0.7
    this.dodgeTimer = DODGE_TIME
    this.dodgeCooldown = 0.24
    this.invuln = 0.34
    this.attack = null
    const dir = moveDir.lengthSq() > 0.05 ? moveDir.clone().normalize() : this.forward
    this.dodgeDir = dir
    this.yaw = Math.atan2(dir.x, dir.z)
    this.events.onDodge?.(this.position.clone(), this.yaw)
  }

  startAttack(heavy) {
    const cfg = heavy ? HEAVY : ATTACKS[this.comboStep % ATTACKS.length]
    if (this.stamina < cfg.stamina * 0.5) {
      this.events.onStaminaFail?.('Vigor insuficiente')
      return
    }
    this.stamina = Math.max(0, this.stamina - cfg.stamina)
    this.staminaDelay = 0.8
    this.attack = {
      heavy,
      stage: heavy ? 3 : this.comboStep,
      time: 0,
      cfg,
      hitDone: false,
      buffered: false,
    }
    if (!heavy) {
      this.events.onCombo?.(this.comboStep + 1)
    }
    const lungeDir = new THREE.Vector3(Math.sin(this.aimYaw), 0, Math.cos(this.aimYaw))
    this.yaw = this.aimYaw
    this.velocity.add(lungeDir.multiplyScalar(cfg.lunge))
  }

  addXp(amount) {
    this.xp += amount
    let leveled = false
    while (this.xp >= this.xpToNext) {
      this.xp -= this.xpToNext
      this.level++
      this.xpToNext = Math.round(90 + this.level * 62)
      this.maxHp = 120 + (this.level - 1) * 16
      this.maxStamina = 100 + (this.level - 1) * 3
      this.hp = this.maxHp
      this.stamina = this.maxStamina
      leveled = true
    }
    if (leveled) this.events.onLevelUp?.(this.level)
  }

  heal(amount) {
    const before = this.hp
    this.hp = Math.min(this.maxHp, this.hp + amount)
    return this.hp - before
  }

  takeDamage(amount, sourcePos) {
    if (this.dead || this.invuln > 0) return false
    const dmg = Math.max(1, amount * (1 - Math.min(0.32, (this.level - 1) * 0.035)))
    this.hp = Math.max(0, this.hp - dmg)
    this.invuln = 0.62
    this.hitstun = 0.26
    this.attack = null
    this.lastHurt = 0
    this.stamina = Math.max(0, this.stamina - 8)
    this.events.onHurt?.(dmg, sourcePos)
    if (this.hp <= 0) {
      this.dead = true
      this.events.onDeath?.()
    }
    return true
  }

  respawn() {
    this.dead = false
    this.hp = this.maxHp
    this.stamina = this.maxStamina
    this.position.copy(this.spawnPoint)
    this.position.y = terrainHeight(this.position.x, this.position.z)
    this.velocity.set(0, 0, 0)
    this.attack = null
    this.dodgeTimer = 0
    this.invuln = 2.0
    this.model.position.copy(this.position)
  }

  consumeHit() {
    if (!this.attack || this.attack.hitDone) return null
    const { time, cfg, heavy, stage } = this.attack
    if (time >= cfg.hitStart && time <= cfg.hitEnd) {
      this.attack.hitDone = true
      return {
        position: this.position.clone(),
        yaw: this.yaw,
        range: cfg.range,
        arc: cfg.arc,
        damage: cfg.damage * (1 + (this.level - 1) * 0.085),
        knock: cfg.knock,
        heavy,
        stage,
      }
    }
    return null
  }

  update(dt, input, time, camera) {
    this.time = time
    if (this.dead) {
      this.updateModel(dt, 0, camera, false)
      this.model.position.copy(this.position)
      return
    }

    this.attackCooldown = Math.max(0, this.attackCooldown - dt)
    this.dodgeCooldown = Math.max(0, this.dodgeCooldown - dt)
    this.invuln = Math.max(0, this.invuln - dt)
    this.hitstun = Math.max(0, this.hitstun - dt)
    this.attackBuffer = Math.max(0, this.attackBuffer - dt)
    this.heavyBuffer = Math.max(0, this.heavyBuffer - dt)
    this.dodgeBuffer = Math.max(0, this.dodgeBuffer - dt)
    this.comboWindow = Math.max(0, this.comboWindow - dt)
    this.lastHurt += dt
    if (!this.attack && this.comboWindow <= 0) this.comboStep = 0

    // stamina
    this.staminaDelay = Math.max(0, this.staminaDelay - dt)
    if (this.staminaDelay <= 0) {
      const regen = this.isDodging ? 0 : (this.sprinting ? 0 : 19)
      this.stamina = Math.min(this.maxStamina, this.stamina + regen * dt)
    }

    // out-of-combat regen
    if (this.lastHurt > 7 && this.hp < this.maxHp) {
      this.hp = Math.min(this.maxHp, this.hp + 1.6 * dt)
    }

    const move = input.move || { x: 0, y: 0 }
    const moveDir = new THREE.Vector3()
    if (Math.abs(move.x) > 0.01 || Math.abs(move.y) > 0.01) {
      const forward = new THREE.Vector3(Math.sin(input.cameraYaw), 0, Math.cos(input.cameraYaw))
      const right = new THREE.Vector3(Math.cos(input.cameraYaw), 0, -Math.sin(input.cameraYaw))
      moveDir.copy(forward).multiplyScalar(move.y).add(right.multiplyScalar(move.x))
      if (moveDir.lengthSq() > 1) moveDir.normalize()
      else if (moveDir.lengthSq() > 0.001) moveDir.normalize()
    }
    const inputMag = Math.min(1, Math.hypot(move.x, move.y))
    this.moving = inputMag > 0.12

    // action buffers
    if (input.attackPressed) this.attackBuffer = 0.26
    if (input.heavyPressed) this.heavyBuffer = 0.26
    if (input.dodgePressed) this.dodgeBuffer = 0.22

    // dodge
    if (this.dodgeTimer > 0) {
      this.dodgeTimer -= dt
      const t = 1 - Math.max(0, this.dodgeTimer) / DODGE_TIME
      const speed = 13.5 * (1 - easing.outCubic(t) * 0.55)
      this.velocity.x = this.dodgeDir.x * speed
      this.velocity.z = this.dodgeDir.z * speed
      if (this.dodgeTimer <= 0) {
        this.dodgeTimer = 0
        this.dodgeBuffer = 0
      }
    } else if (this.dodgeBuffer > 0 && this.dodgeCooldown <= 0 && this.hitstun <= 0 && !this.attack) {
      this.startDodge(moveDir)
    } else if (!this.attack && this.hitstun <= 0) {
      // movement
      this.sprinting = input.sprint && inputMag > 0.2 && this.stamina > 1
      const speed = this.sprinting ? 9.6 : 6.4
      const targetVel = moveDir.multiplyScalar(speed * (this.moving ? 1 : 0))
      this.velocity.x = damp(this.velocity.x, targetVel.x, this.moving ? 12 : 9, dt)
      this.velocity.z = damp(this.velocity.z, targetVel.z, this.moving ? 12 : 9, dt)
      if (this.sprinting && this.moving) this.stamina = Math.max(0, this.stamina - 15 * dt)
      // face movement direction
      if (this.moving) {
        const targetYaw = Math.atan2(moveDir.x, moveDir.z)
        this.yaw = dampAngle(this.yaw, targetYaw, 13, dt)
      }
      // buffer attack
      if (this.heavyBuffer > 0 && this.attackCooldown <= 0) {
        this.heavyBuffer = 0
        this.startAttack(true)
      } else if (this.attackBuffer > 0 && this.attackCooldown <= 0) {
        this.attackBuffer = 0
        this.startAttack(false)
      }
    } else if (this.attack) {
      // slight movement retention during attacks
      this.velocity.x = damp(this.velocity.x, 0, 7, dt)
      this.velocity.z = damp(this.velocity.z, 0, 7, dt)
      if (this.attackBuffer > 0 && this.attack.time > this.attack.cfg.hitStart + 0.02 && !this.attack.buffered) {
        this.attack.buffered = true
      }
    } else {
      this.velocity.x = damp(this.velocity.x, 0, 10, dt)
      this.velocity.z = damp(this.velocity.z, 0, 10, dt)
    }

    // integrate
    const nextX = this.position.x + this.velocity.x * dt
    const nextZ = this.position.z + this.velocity.z * dt
    if (this.world.canWalk(nextX, this.position.z) || this.isDodging) {
      if (Math.hypot(nextX, this.position.z) < 201) this.position.x = nextX
    } else {
      this.velocity.x *= 0.2
    }
    if (this.world.canWalk(this.position.x, nextZ) || this.isDodging) {
      if (Math.hypot(this.position.x, nextZ) < 201) this.position.z = nextZ
    } else {
      this.velocity.z *= 0.2
    }
    const ground = terrainHeight(this.position.x, this.position.z)
    this.position.y = damp(this.position.y, ground, 18, dt)

    // attack progression
    if (this.attack) {
      this.attack.time += dt
      if (this.attack.time >= this.attack.cfg.duration) {
        const wasHeavy = this.attack.heavy
        const stage = this.attack.stage
        const buffered = this.attack.buffered || this.attackBuffer > 0
        this.attack = null
        this.attackCooldown = wasHeavy ? 0.24 : 0.09
        if (wasHeavy) {
          this.comboStep = 0
          this.comboWindow = 0
        } else if (stage >= 2) {
          this.comboStep = 0
          this.comboWindow = 0.32
        } else {
          this.comboStep = stage + 1
          this.comboWindow = 0.62
        }
        if (buffered) {
          this.attackBuffer = 0.16
          this.heavyBuffer = 0
        }
      }
    }

    // footsteps
    const speed = Math.hypot(this.velocity.x, this.velocity.z)
    if (speed > 0.8 && !this.isAttacking) {
      const prev = Math.sin(this.walkPhase)
      this.walkPhase += dt * (this.sprinting ? 13 : 9.2)
      const now = Math.sin(this.walkPhase)
      if (prev > 0 && now <= 0) this.events.onStep?.()
    } else {
      this.walkPhase += dt * 1.6
    }

    this.updateModel(dt, inputMag, camera, speed)
    this.model.position.copy(this.position)
    this.model.rotation.y = this.modelYaw
  }

  updateModel(dt, moveMag, camera, speed) {
    const p = this.model.userData.parts
    const t = this.time
    const baseArmL = 0.1
    const baseArmR = -0.1
    let tArmLx = 0
    let tArmLz = baseArmL
    let tArmRx = 0
    let tArmRz = baseArmR
    let tForeLx = 0.18
    let tForeRx = -0.28
    let tSwordX = 2.62
    let tSwordZ = 0.12
    let tTorsoY = 0
    let tTorsoX = 0
    let tTorsoZ = 0
    let tHeadY = 0
    let tCapeX = 0
    let legLx = 0
    let legRx = 0
    let shinLx = 0
    let shinRx = 0
    let bob = 0
    let lean = 0
    let modelScaleY = 1

    const idle = Math.sin(t * 1.8)
    tCapeX = 0.06 + Math.sin(t * 2.1) * 0.03
    tArmLz += idle * 0.015
    bob = idle * 0.012

    if (moveMag > 0.1 && speed > 0.5 && !this.attack && !this.isDodging) {
      const swing = Math.sin(this.walkPhase)
      const swing2 = Math.sin(this.walkPhase + Math.PI)
      const amp = Math.min(1, speed / 6) * (this.sprinting ? 1.15 : 0.8)
      legLx = swing * 0.62 * amp
      legRx = swing2 * 0.62 * amp
      shinLx = Math.max(0, swing2) * -0.55 * amp
      shinRx = Math.max(0, swing) * -0.55 * amp
      tArmLx = swing2 * 0.38 * amp
      tArmRx = swing * 0.3 * amp
      tTorsoZ = swing * 0.05 * amp
      tTorsoY = swing * 0.06 * amp
      bob = Math.abs(Math.sin(this.walkPhase)) * 0.045
      lean = 0.04 + amp * 0.05
      tCapeX = 0.15 + amp * 0.3 + Math.sin(this.walkPhase * 2) * 0.05
    }

    if (this.isDodging) {
      const tD = 1 - this.dodgeTimer / DODGE_TIME
      const k = Math.sin(Math.min(1, tD * 1.2) * Math.PI)
      lean = 0.32 * k
      tTorsoX = 0.35 * k
      tArmLz = 0.5 * k
      tArmRz = -0.5 * k
      tForeRx = -1.1 * k
      tSwordX = 2.9
      legLx = -0.65 * k
      legRx = 0.5 * k
      shinLx = -0.8 * k
      bob = -0.18 * k
      modelScaleY = 1 - 0.06 * k
    }

    if (this.attack) {
      const a = this.attack
      const dur = a.cfg.duration
      const tt = clamp(a.time / dur, 0, 1)
      const wind = clamp(tt / 0.34, 0, 1)
      const strike = clamp((tt - 0.3) / 0.32, 0, 1)
      const rec = clamp((tt - 0.66) / 0.34, 0, 1)
      const swing = easing.outCubic(strike) * (1 - easing.inOutSine(rec) * 0.65)
      const windK = easing.outCubic(wind) * (1 - strike * 0.55)

      if (a.heavy) {
        tArmRx = -2.0 * windK + 2.5 * swing
        tArmRz = -0.35 * windK + 0.3 * swing
        tForeRx = -1.5 * windK + 0.4 * swing
        tSwordX = 2.0 * windK + 2.1 * swing
        tSwordZ = 0.1
        tTorsoY = -0.75 * windK + 0.65 * swing
        tTorsoX = -0.22 * windK + 0.3 * swing
        tArmLz = 0.5 * windK + 0.2 * swing
        tArmLx = -1.1 * windK + 0.5 * swing
        lean = 0.22 * windK + 0.12 * swing
        bob = 0.18 * windK - 0.1 * swing
        legLx = -0.3 * swing
        legRx = 0.35 * swing
        shinRx = -0.4 * swing
      } else if (a.stage === 0) {
        tArmRz = -1.15 * windK + 1.55 * swing
        tArmRx = -0.35 * windK + 1.1 * swing
        tForeRx = -1.35 * windK + 0.55 * swing
        tSwordX = 1.3 * windK + 0.8 * swing
        tSwordZ = 0.0
        tTorsoY = -0.62 * windK + 0.7 * swing
        tArmLz = 0.35 * windK - 0.15 * swing
        tArmLx = -0.25 * swing
        tHeadY = 0.18 * windK - 0.2 * swing
        lean = 0.04 + 0.12 * swing
      } else if (a.stage === 1) {
        tArmRz = 1.05 * windK - 1.55 * swing
        tArmRx = 0.95 * windK - 0.35 * swing
        tForeRx = 0.5 * windK - 1.1 * swing
        tSwordX = 2.0 - 0.6 * swing
        tTorsoY = 0.55 * windK - 0.75 * swing
        tArmLz = -0.2 * windK + 0.4 * swing
        tHeadY = -0.15 * windK + 0.2 * swing
        lean = 0.04 + 0.1 * swing
        legLx = 0.25 * swing
      } else {
        // spin finisher
        tTorsoY = -1.1 * windK + 1.8 * swing
        tArmRz = -1.0 * windK + 1.4 * swing
        tArmRx = -1.3 * windK + 1.8 * swing
        tForeRx = -1.0 * windK + 0.3 * swing
        tSwordX = 2.2
        tSwordZ = 0.2
        tArmLz = 0.7 * windK - 0.35 * swing
        tArmLx = -0.5 * windK + 0.7 * swing
        lean = 0.1 + 0.15 * swing
        bob = 0.12 * windK - 0.06 * swing
        legLx = -0.4 * swing
        legRx = 0.4 * swing
        shinRx = -0.5 * swing
      }
      tCapeX = 0.12 + 0.35 * swing
      if (this.hitstun > 0) {
        tTorsoX -= 0.3
      }
    }

    if (this.hitstun > 0) {
      const k = clamp(this.hitstun / 0.26, 0, 1)
      lean = -0.22 * k
      tTorsoX = -0.22 * k
      tArmLx = -0.4 * k
      tArmRx = -0.4 * k
      bob = -0.03 * k
      tCapeX = 0.35 * k
    }

    if (this.dead) {
      lean = -1.2
      bob = -0.7
      tArmLx = 0.5
      tArmRx = 0.5
      tCapeX = 0.5
    }

    const lam = this.isAttacking ? 26 : this.isDodging ? 20 : 14
    p.armL.rotation.x = damp(p.armL.rotation.x, tArmLx, lam, dt)
    p.armL.rotation.z = damp(p.armL.rotation.z, tArmLz, lam, dt)
    p.armR.rotation.x = damp(p.armR.rotation.x, tArmRx, lam, dt)
    p.armR.rotation.z = damp(p.armR.rotation.z, tArmRz, lam, dt)
    p.foreL.rotation.x = damp(p.foreL.rotation.x, tForeLx, lam, dt)
    p.foreR.rotation.x = damp(p.foreR.rotation.x, tForeRx, lam, dt)
    p.sword.rotation.x = damp(p.sword.rotation.x, tSwordX, lam, dt)
    p.sword.rotation.z = damp(p.sword.rotation.z, tSwordZ, lam, dt)
    if (!this.attack || !this.attack.hitDone) {
      p.swordGlow.material.opacity = 0.2 + Math.sin(t * 3.1) * 0.08
    } else {
      p.swordGlow.material.opacity = 0.55
    }
    p.torso.rotation.y = damp(p.torso.rotation.y, tTorsoY, lam, dt)
    p.torso.rotation.x = damp(p.torso.rotation.x, tTorsoX, lam, dt)
    p.torso.rotation.z = damp(p.torso.rotation.z, tTorsoZ, lam, dt)
    p.head.rotation.y = damp(p.head.rotation.y, tHeadY, lam, dt)
    p.head.rotation.x = damp(p.head.rotation.x, this.attack ? -0.08 : 0, 8, dt)

    p.capePivot.rotation.x = damp(p.capePivot.rotation.x, tCapeX, 6, dt)
    p.capePivot.rotation.z = damp(p.capePivot.rotation.z, -tTorsoZ * 0.7 + Math.sin(t * 1.2) * 0.02, 6, dt)
    p.scarfTail.rotation.x = damp(p.scarfTail.rotation.x, 0.4 + tCapeX * 1.4, 4, dt)

    p.legL.rotation.x = damp(p.legL.rotation.x, legLx, 20, dt)
    p.legR.rotation.x = damp(p.legR.rotation.x, legRx, 20, dt)
    if (p.shinLGroup) p.shinLGroup.rotation.x = damp(p.shinLGroup.rotation.x, shinLx, 18, dt)
    if (p.shinRGroup) p.shinRGroup.rotation.x = damp(p.shinRGroup.rotation.x, shinRx, 18, dt)

    this.model.position.y = this.position.y + bob
    this.model.scale.y = damp(this.model.scale.y, modelScaleY, 12, dt)
    this.model.rotation.x = damp(this.model.rotation.x, lean, 10, dt)
    if (this.isDodging || this.attack || this.hitstun > 0) {
      this.modelYaw = dampAngle(this.modelYaw, this.yaw, 24, dt)
    } else {
      this.modelYaw = dampAngle(this.modelYaw, this.yaw, 12, dt)
    }

    // sword trail position handled by game fx via events
    void camera
    void p.bladeRune
  }

  get attackProgress() {
    if (!this.attack) return 0
    return clamp(this.attack.time / this.attack.cfg.duration, 0, 1)
  }
}

export { ATTACKS, HEAVY, DODGE_TIME }

import * as THREE from 'three'
import { softDiscTexture, slashArcGeometry, rand, randInt, clamp } from './engine.js'

const MAX_PARTICLES = 900

export class FX {
  constructor(scene, camera) {
    this.scene = scene
    this.camera = camera
    this.particles = []
    this.rings = []
    this.projectiles = []
    this.trails = []
    this.damageLayer = document.getElementById('damageLayer')

    const geo = new THREE.BufferGeometry()
    const positions = new Float32Array(MAX_PARTICLES * 3)
    const colors = new Float32Array(MAX_PARTICLES * 3)
    const sizes = new Float32Array(MAX_PARTICLES)
    const alphas = new Float32Array(MAX_PARTICLES)
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    geo.setAttribute('size', new THREE.BufferAttribute(sizes, 1))
    geo.setAttribute('alpha', new THREE.BufferAttribute(alphas, 1))
    geo.setDrawRange(0, 0)

    this.particleGeo = geo
    this.particleMat = new THREE.ShaderMaterial({
      uniforms: { uTex: { value: softDiscTexture(64, 'rgba(255,255,255,0.95)', 'rgba(255,255,255,0)') } },
      vertexShader: `
        attribute float size;
        attribute float alpha;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = color;
          vAlpha = alpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = size * (260.0 / max(0.1, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        uniform sampler2D uTex;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 tex = texture2D(uTex, gl_PointCoord);
          if (tex.a < 0.01) discard;
          gl_FragColor = vec4(vColor, tex.a * vAlpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      vertexColors: true,
    })
    this.points = new THREE.Points(geo, this.particleMat)
    this.points.frustumCulled = false
    scene.add(this.points)

    this.slashGeo = slashArcGeometry(2.5, 0.5, Math.PI * 1.0, 30)
    this.ringGeo = new THREE.RingGeometry(0.86, 1, 48)
    this.ringGeo.rotateX(-Math.PI / 2)

    this.tmp = new THREE.Vector3()
    this.tmp2 = new THREE.Vector3()
  }

  /* ── particles ── */
  spawnParticles(position, color, count = 12, opts = {}) {
    const {
      speed = 4, spread = 1, gravity = 8, size = 0.4, life = 0.7,
      upward = 0.6, colorJitter = 0.1,
    } = opts
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) this.particles.shift()
      const dir = new THREE.Vector3(
        (Math.random() - 0.5) * 2 * spread,
        Math.random() * upward + (upward > 0 ? 0.1 : -0.5),
        (Math.random() - 0.5) * 2 * spread,
      ).normalize()
      const spd = speed * (0.35 + Math.random() * 0.85)
      const col = c.clone().offsetHSL((Math.random() - 0.5) * colorJitter, 0, (Math.random() - 0.5) * colorJitter)
      this.particles.push({
        pos: new THREE.Vector3(position.x + (Math.random() - 0.5) * 0.4, position.y + (Math.random() - 0.5) * 0.4, position.z + (Math.random() - 0.5) * 0.4),
        vel: dir.multiplyScalar(spd),
        color: col,
        life: life * (0.6 + Math.random() * 0.8),
        maxLife: life,
        size: size * (0.6 + Math.random() * 0.9),
        gravity,
      })
    }
  }

  spawnDirectional(position, direction, color, count = 8, opts = {}) {
    const c = new THREE.Color(color)
    const dir = direction.clone().normalize()
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) this.particles.shift()
      const spread = new THREE.Vector3((Math.random() - 0.5) * 1.6, (Math.random() - 0.5) * 1.6, (Math.random() - 0.5) * 1.6)
      const vel = dir.clone().add(spread).normalize().multiplyScalar((opts.speed || 7) * (0.4 + Math.random()))
      this.particles.push({
        pos: position.clone(),
        vel,
        color: c.clone().offsetHSL((Math.random() - 0.5) * 0.05, 0, (Math.random() - 0.5) * 0.1),
        life: (opts.life || 0.5) * (0.6 + Math.random() * 0.7),
        maxLife: opts.life || 0.5,
        size: (opts.size || 0.3) * (0.7 + Math.random() * 0.8),
        gravity: opts.gravity ?? 4,
      })
    }
  }

  updateParticles(dt) {
    const positions = this.particleGeo.attributes.position.array
    const colors = this.particleGeo.attributes.color.array
    const sizes = this.particleGeo.attributes.size.array
    const alphas = this.particleGeo.attributes.alpha.array
    let n = 0
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i]
      p.life -= dt
      if (p.life <= 0) { this.particles.splice(i, 1); continue }
      p.vel.y -= p.gravity * dt
      p.vel.multiplyScalar(1 - 1.4 * dt)
      p.pos.addScaledVector(p.vel, dt)
      if (p.pos.y < -1.3) { p.pos.y = -1.3; p.vel.y *= -0.3 }
    }
    for (const p of this.particles) {
      if (n >= MAX_PARTICLES) break
      positions[n * 3] = p.pos.x
      positions[n * 3 + 1] = p.pos.y
      positions[n * 3 + 2] = p.pos.z
      colors[n * 3] = p.color.r
      colors[n * 3 + 1] = p.color.g
      colors[n * 3 + 2] = p.color.b
      const k = clamp(p.life / p.maxLife, 0, 1)
      sizes[n] = p.size * (0.5 + k * 0.7)
      alphas[n] = k * k
      n++
    }
    this.particleGeo.setDrawRange(0, n)
    this.particleGeo.attributes.position.needsUpdate = true
    this.particleGeo.attributes.color.needsUpdate = true
    this.particleGeo.attributes.size.needsUpdate = true
    this.particleGeo.attributes.alpha.needsUpdate = true
  }

  /* ── slash ── */
  slash(position, yaw, { heavy = false, color = 0x9ffff0, scale = 1 } = {}) {
    const mat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.85,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    const mesh = new THREE.Mesh(this.slashGeo, mat)
    mesh.position.copy(position)
    mesh.position.y += heavy ? 1.35 : 1.15
    mesh.rotation.y = yaw
    mesh.rotation.x = heavy ? 0.85 : 0.15
    mesh.rotation.z = heavy ? 0 : -0.35
    mesh.scale.setScalar(scale * (heavy ? 1.4 : 1))
    mesh.renderOrder = 4
    this.scene.add(mesh)
    this.trails.push({ mesh, life: heavy ? 0.32 : 0.24, maxLife: heavy ? 0.32 : 0.24, heavy })
  }

  updateTrails(dt) {
    for (let i = this.trails.length - 1; i >= 0; i--) {
      const t = this.trails[i]
      t.life -= dt
      const k = clamp(t.life / t.maxLife, 0, 1)
      t.mesh.material.opacity = k * 0.9
      t.mesh.rotation.y += (t.heavy ? -3.2 : 4.6) * dt
      t.mesh.scale.multiplyScalar(1 + dt * 1.4)
      if (t.life <= 0) {
        this.scene.remove(t.mesh)
        t.mesh.material.dispose()
        this.trails.splice(i, 1)
      }
    }
  }

  /* ── shockwave ── */
  shockwave(position, color = 0xffc48a, maxRadius = 6, duration = 0.55) {
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.85, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    })
    const mesh = new THREE.Mesh(this.ringGeo, mat)
    mesh.position.copy(position)
    mesh.position.y += 0.12
    mesh.scale.setScalar(0.4)
    this.scene.add(mesh)
    this.rings.push({ mesh, life: duration, maxLife: duration, maxRadius })
  }

  updateRings(dt) {
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i]
      r.life -= dt
      const k = 1 - clamp(r.life / r.maxLife, 0, 1)
      const radius = 0.4 + (r.maxRadius - 0.4) * (1 - Math.pow(1 - k, 3))
      r.mesh.scale.setScalar(radius)
      r.mesh.material.opacity = (1 - k) * 0.8
      if (r.life <= 0) {
        this.scene.remove(r.mesh)
        r.mesh.material.dispose()
        this.rings.splice(i, 1)
      }
    }
  }

  /* ── projectile ── */
  spawnProjectile({ position, target, speed = 12, damage = 10, color = 0x7fe6ff, owner = 'enemy', homing = 0, radius = 0.42, splash = 0 }) {
    const group = new THREE.Group()
    const core = new THREE.Mesh(
      new THREE.IcosahedronGeometry(radius, 0),
      new THREE.MeshBasicMaterial({ color }),
    )
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: softDiscTexture(64, 'rgba(255,255,255,0.9)', 'rgba(255,255,255,0)'),
      color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false,
    }))
    glow.scale.setScalar(radius * 5)
    group.add(core, glow)
    group.position.copy(position)
    this.scene.add(group)
    const dir = target.clone().sub(position).normalize()
    const p = {
      group, velocity: dir.multiplyScalar(speed), life: 4.5, damage, color, owner,
      homing, radius, splash, trailTimer: 0,
    }
    this.projectiles.push(p)
    return p
  }

  updateProjectiles(dt, world, player, onHitPlayer) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i]
      p.life -= dt
      if (p.homing > 0 && p.owner === 'enemy') {
        const target = player.position.clone()
        target.y += 1.1
        const desired = target.sub(p.group.position).normalize().multiplyScalar(p.velocity.length())
        p.velocity.lerp(desired, 1 - Math.exp(-p.homing * dt))
      }
      p.group.position.addScaledVector(p.velocity, dt)
      p.group.rotation.x += dt * 6
      p.group.rotation.y += dt * 4
      p.trailTimer -= dt
      if (p.trailTimer <= 0) {
        p.trailTimer = 0.045
        this.spawnParticles(p.group.position, p.color, 2, { speed: 0.6, gravity: 0, size: 0.32, life: 0.35, spread: 0.4, upward: 0 })
      }
      const ground = world.heightAt(p.group.position.x, p.group.position.z)
      let hit = false
      if (p.owner === 'enemy') {
        const dx = p.group.position.x - player.position.x
        const dz = p.group.position.z - player.position.z
        const dy = p.group.position.y - (player.position.y + 1.0)
        if (dx * dx + dz * dz < (p.radius + 0.8) ** 2 && Math.abs(dy) < 1.3) {
          onHitPlayer?.(p)
          hit = true
        }
      }
      if (p.group.position.y < ground + 0.2 || p.group.position.y > ground + 25) hit = true
      if (p.life <= 0) hit = true
      if (hit) {
        this.spawnParticles(p.group.position, p.color, 16, { speed: 5, gravity: 6, size: 0.5, life: 0.6 })
        this.scene.remove(p.group)
        this.projectiles.splice(i, 1)
      }
    }
  }

  /* ── damage numbers ── */
  damageNumber(worldPosition, text, cls = '') {
    if (!this.damageLayer) return
    const pos = worldPosition.clone()
    pos.y += 1.4
    pos.project(this.camera)
    if (pos.z > 1) return
    const x = (pos.x * 0.5 + 0.5) * window.innerWidth
    const y = (-pos.y * 0.5 + 0.5) * window.innerHeight
    if (x < -100 || x > window.innerWidth + 100 || y < -100 || y > window.innerHeight + 100) return
    const el = document.createElement('div')
    el.className = `dmg ${cls}`
    el.textContent = text
    el.style.left = `${x}px`
    el.style.top = `${y}px`
    el.style.setProperty('--drift', `${(Math.random() - 0.5) * 40}px`)
    this.damageLayer.appendChild(el)
    setTimeout(() => el.remove(), 1000)
  }

  burst(position, color, count = 18, opts = {}) {
    this.spawnParticles(position, color, count, opts)
  }

  update(dt) {
    this.updateParticles(dt)
    this.updateTrails(dt)
    this.updateRings(dt)
  }

  clear() {
    for (const p of this.projectiles) this.scene.remove(p.group)
    this.projectiles.length = 0
    for (const t of this.trails) this.scene.remove(t.mesh)
    this.trails.length = 0
    for (const r of this.rings) this.scene.remove(r.mesh)
    this.rings.length = 0
    this.particles.length = 0
  }
}

export function randomPointInCircle(radius) {
  const a = Math.random() * Math.PI * 2
  const r = Math.sqrt(Math.random()) * radius
  return [Math.cos(a) * r, Math.sin(a) * r]
}

